mapper.sql:
SELECT COUNT(1) OVER() AS TOTAL_CNT , ROW_NUMBER() OVER (ORDER BY A.ACTV_DTTM DESC, A.USER_ACTV_ID DESC) AS LINE_NO , A.USER_ACTV_ID , A.ACTV_DTTM , A.CNTN_IP , A.USER_TYCD , A.NAVI_POSNM , U.USER_ID , U.USER_RPRS_ID , U.USERNM , U.STDNT_NO , S.SBJCT_ID , S.SBJCTNM , S.SBJCT_YR , S.SBJCT_SMSTR , S.DVCLAS_NO , D.DEPTNM AS DEPT_NM , O.ORGNM FROM TB_LMS_LOG_USER_ACTV A INNER JOIN TB_LMS_USER U ON U.USER_ID = A.USER_ID INNER JOIN TB_LMS_SBJCT S ON S.SBJCT_ID = A.SBJCT_ID LEFT JOIN TB_LMS_DEPT D ON D.DEPT_ID = S.DEPT_ID INNER JOIN TB_LMS_ORG O ON O.ORG_ID = U.ORG_ID WHERE A.SBJCT_ID = #{sbjctId}
AND A.ACTV_DTTM >= #{searchFrom} AND A.ACTV_DTTM <= #{searchTo}
AND A.USER_TYCD IN ('PROF', 'COPROF')
AND A.USER_TYCD = #{userTycd}
AND A.USER_ID IN ( SELECT USER_ID FROM TB_LMS_USER WHERE USER_RPRS_ID = #{searchText} OR STDNT_NO = #{searchText} OR USERNM LIKE '%' || #{searchText} || '%' )
ORDER BY A.ACTV_DTTM DESC, A.USER_ACTV_ID DESC

mapper.select:
/* SQL ID : LogUserActvDAO.userCntnStsList 설 명 : 사용자 접속 현황 목록 (현재시간보다 120분 전까지의 접속기록조회) */ SELECT ROW_NUMBER() OVER(ORDER BY LOG.ACTV_DTTM DESC) AS LINE_NO , ORG.ORGNM , DEPT.DEPTNM , LOG.SBJCT_ID , SBJ.SBJCTNM || (CASE WHEN SBJ.DVCLAS_NO IS NOT NULL THEN ' (' || SBJ.DVCLAS_NO || '반)' ELSE '' END ) AS SBJCTNM , LOG.USER_ID , USR.STDNT_NO , STD.SCYR , USR.USERNM , CNTCT.CNTCT , LOG.ACTV_DTTM FROM ( SELECT ROW_NUMBER() OVER(PARTITION BY SBJCT_ID, USER_ID ORDER BY ACTV_DTTM DESC) AS RN , SBJCT_ID, USER_ID, ACTV_DTTM, ACTV_DATETIME FROM TB_LMS_LOG_USER_ACTV WHERE USER_TYCD = #{userTycd} AND SBJCT_ID IS NOT NULL ) LOG JOIN TB_LMS_SBJCT SBJ ON SBJ.SBJCT_ID = LOG.SBJCT_ID JOIN TB_LMS_USER USR ON USR.USER_ID = LOG.USER_ID JOIN TB_LMS_USER_CNTCT CNTCT ON USR.USER_ID = CNTCT.USER_ID AND CNTCT_TYCD = 'MBL_PHN' LEFT JOIN TB_LMS_ATNDLC STD ON SBJ.SBJCT_ID = STD.SBJCT_ID AND USR.USER_ID = STD.USER_ID JOIN TB_LMS_SMSTR_CHRT SMSTR ON SBJ.SMSTR_CHRT_ID = SMSTR.SMSTR_CHRT_ID JOIN TB_LMS_DEPT DEPT ON SBJ.DEPT_ID = DEPT.DEPT_ID JOIN TB_LMS_ORG ORG ON DEPT.ORG_ID = ORG.ORG_ID WHERE LOG.RN = 1 AND LOG.ACTV_DATETIME >= (SYSDATE - NUMTODSINTERVAL(120, 'MINUTE')) /* 혙ㄴ*/
AND SMSTR.DGRS_YR = #{dgrsYr}
AND SMSTR.DGRS_SMSTR_CHRT = #{dgrsSmstr}
AND ORG.ORG_ID = #{orgId}
AND ( LOWER(SBJ.SBJCTNM) LIKE '%' || LOWER(#{searchValue}) || '%' OR LOWER(USR.USERNM) LIKE '%' || LOWER(#{searchValue}) || '%' )
ORDER BY LOG.ACTV_DTTM DESC

mapper.sql:
WITH BASE AS ( SELECT ROW_NUMBER() OVER(ORDER BY LUA.ACTV_DTTM DESC, LUA.USER_ACTV_ID DESC) AS LINE_NO , LUA.USER_ACTV_ID , LUA.ORG_ID , ORG.ORGNM , SMSTR.DGRS_YR , SMSTR.DGRS_SMSTR_CHRT , LUA.DEPT_ID , DEPT.DEPTNM , LUA.SBJCT_ID , SBJ.SBJCTNM , SBJ.CRCLMN_NO , SBJ.DVCLAS_NO , USR.STDNT_NO , USR.USER_ID , USR.USERNM , LUA.USER_TYCD , ACTN.SRVC_ACTN_GBNCD , CD.CDNM AS SRVC_ACTN_GBNNM , ACTN.SRVC_ACTN_EXPLN , ACTN.SRVC_ACTN_TYCD , LUA.USER_REQ_URL , LUA.CNTN_IP , LUA.ACTV_DTTM FROM TB_LMS_LOG_USER_ACTV LUA JOIN TB_LMS_USER USR ON USR.USER_ID = LUA.USER_ID LEFT JOIN TB_LMS_SBJCT SBJ ON SBJ.SBJCT_ID = LUA.SBJCT_ID LEFT JOIN TB_LMS_SMSTR_CHRT SMSTR ON SMSTR.SMSTR_CHRT_ID = LUA.SMSTR_CHRT_ID LEFT JOIN TB_LMS_ORG ORG ON ORG.ORG_ID = LUA.ORG_ID LEFT JOIN TB_LMS_DEPT DEPT ON DEPT.ORG_ID = LUA.ORG_ID AND DEPT.DEPT_ID = LUA.DEPT_ID LEFT JOIN TB_LMS_SRVC_ACTN ACTN ON ACTN.USER_REQ_URL = LUA.USER_REQ_URL AND ACTN.REQ_TYCD = LUA.REQ_TYCD LEFT JOIN TB_LMS_CMMN_CD CD ON CD.ORG_ID = LUA.ORG_ID AND CD.UP_CD = 'SRVC_ACTN_GBNCD' AND CD.CD = ACTN.SRVC_ACTN_GBNCD AND CD.LANG_CD = NVL(#{langCd}, 'ko') AND CD.USEYN = 'Y' WHERE 1 = 1
AND LUA.ORG_ID = #{orgId}
AND LUA.SMSTR_CHRT_ID = #{smstrChrtId}
AND LUA.DEPT_ID = #{deptId}
AND LUA.SBJCT_ID = #{sbjctId}
AND LUA.ACTV_DTTM >= #{searchSdttm}
AND LUA.ACTV_DTTM <= #{searchEdttm}
AND INSTR(',' || #{userTycds} || ',', ',' || LUA.USER_TYCD || ',') > 0
AND ACTN.SRVC_ACTN_GBNCD = #{srvcActnGbncd}
AND ( LOWER(USR.STDNT_NO) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) OR LOWER(USR.USER_ID) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) OR LOWER(USR.USERNM) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) )
) SELECT BASE.LINE_NO , BASE.USER_ACTV_ID , BASE.ORG_ID , BASE.ORGNM , BASE.DGRS_YR , BASE.DGRS_SMSTR_CHRT , BASE.DEPT_ID , BASE.DEPTNM , BASE.SBJCT_ID , BASE.SBJCTNM , BASE.CRCLMN_NO , BASE.DVCLAS_NO , BASE.STDNT_NO , BASE.USER_ID , BASE.USERNM , BASE.USER_TYCD , BASE.SRVC_ACTN_GBNCD , BASE.SRVC_ACTN_GBNNM , BASE.SRVC_ACTN_EXPLN , BASE.SRVC_ACTN_TYCD , BASE.USER_REQ_URL , BASE.CNTN_IP , BASE.ACTV_DTTM FROM BASE

mapper.select:
/* SQL ID : LogUserActvDAO.listUserActvHstrySbjct 내용 : 사용자접속이력 검색조건 과목 목록 조회 */ SELECT SBJ.SBJCT_ID , SBJ.SBJCTNM , SBJ.CRCLMN_NO , SBJ.DVCLAS_NO FROM TB_LMS_SBJCT SBJ JOIN TB_LMS_SMSTR_CHRT SMSTR ON SMSTR.SMSTR_CHRT_ID = SBJ.SMSTR_CHRT_ID WHERE NVL(SBJ.DELYN, 'N') = 'N' AND NVL(SBJ.USEYN, 'Y') = 'Y'
AND SMSTR.ORG_ID = #{orgId}
AND SBJ.DEPT_ID = #{deptId}
AND SBJ.SMSTR_CHRT_ID = #{smstrChrtId}
ORDER BY SBJ.SBJCTNM, SBJ.DVCLAS_NO
